'use strict';
const $ = (s, root = document) => root.querySelector(s);
const icon = name => `<i class="ph ph-${name}" aria-hidden="true"></i>`;
const escapeText = text => String(text).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navItems = [{id:'today',label:'今日',icon:'house'},{id:'team',label:'小队',icon:'users'},{id:'checkin',label:'打卡',icon:'plus'},{id:'report',label:'周报',icon:'chart-bar'},{id:'plans',label:'计划',icon:'squares-four'}];
const pages = {today:'今日',team:'小队',checkin:'打卡',report:'周报',plans:'计划',settings:'我的与设置',invite:'邀请与加入',memo:'确认纪要',success:'盖章成功',recognizing:'识别照片',notifications:'通知',ai:'自定义 AI',timer:'运动计时',history:'打卡历史',scanner:'扫码加入',join:'加入小队'};
const photoData = [
 {id:'run',src:'assets/run.jpg',name:'户外运动',category:'运动',confidence:'96%',memo:'今天出门跑步，用一张沿途照片记录这次出发。'},
 {id:'book',src:'assets/book.jpg',name:'阅读时刻',category:'学习',confidence:'88%',memo:'今天留了一段时间阅读。具体章节和页码尚未记录。'},
 {id:'meal',src:'assets/meal.jpg',name:'一餐蔬食',category:'饮食',confidence:'93%',memo:'这餐包含绿叶菜与蔬菜。份量和食材可以继续补充。'}
];
const initialState = () => ({selected:[],category:'ALL',scenario:'normal',stamped:false,liked:false,poked:false,reportMode:'mine',reportShared:false,notifications:true,theme:'light',notes:'',memoEdited:false,labels:{run:'运动',book:'学习',meal:'饮食'},joinCode:'',joined:false,timerStart:null,timerElapsed:0,aiSaved:false});
let state = initialState();
let activeRoute = 'today';
let recognitionTimer;
let toastTimer;
let timerTick;
let customPhotos = [];
const allPhotos = () => [...photoData, ...customPhotos];
const selectedPhotos = () => allPhotos().filter(p => state.selected.includes(p.id));
const avatar = (name, cls='') => `<span class="avatar ${cls}" aria-hidden="true">${name}</span>`;
const primary = (label, action, ic='arrow-right', disabled=false) => `<button class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}${icon(ic)}</button>`;
const secondary = (label, action, ic='') => `<button class="secondary" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
function topbar(title='',back='today') {
 if(title) return `<header class="topbar"><div class="back-title"><button class="icon-btn" data-nav="${back}" aria-label="返回">${icon('arrow-left')}</button><span>${title}</span></div><button class="icon-btn" data-action="overview" aria-label="查看原型体验路线">${icon('dots-three')}</button></header>`;
 return `<header class="topbar"><button class="topbar-person" data-nav="settings" aria-label="林一，打开设置">${avatar('一','me')}<span><small>11 月 19 日，星期四</small><strong>早上好，林一</strong></span></button><div class="topbar-actions"><button class="icon-btn" data-nav="notifications" aria-label="通知，2 条未读">${icon('bell')}<span class="notification-dot"></span></button><button class="icon-btn" data-nav="settings" aria-label="设置">${icon('gear')}</button></div></header>`;
}
function today(){return `${topbar()}<h1 class="page-title">今天，<br>也向前<span class="accent">一点。</span></h1><div class="week-strip" aria-label="本周日期，19 日为今天">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="day ${i===3?'active':i<3?'past':''}"><span>${d}</span><b>${16+i}</b></div>`).join('')}</div><section class="photo-feature" aria-label="今日运动计划"><img src="assets/run.jpg" alt="穿运动鞋在户外石阶上跑步的人" fetchpriority="high"><div class="photo-top"><span class="photo-tag">${icon('person-simple-run')}今天的下一步</span><span>21:00 前</span></div><div class="photo-bottom"><div><h2>${state.stamped?'这一步，完成了。':'去外面，跑一会儿。'}</h2><p>${state.stamped?'今天的运动已盖章，队友可以看见':'每周三次 · 给自己 30 分钟'}</p></div><button class="round-action" data-nav="${state.stamped?'history':'checkin'}" aria-label="${state.stamped?'查看运动记录':'去打卡'}">${icon(state.stamped?'check':'arrow-up-right')}</button></div></section><div class="section-head"><h2>我的今天</h2><button class="text-button" data-nav="plans">${state.stamped?'3':'2'} / 3 已完成 ${icon('arrow-up-right')}</button></div><button class="plan-row" data-action="memo-view" data-id="book"><span class="plan-icon">${icon('book-open')}</span><span class="plan-text"><strong>读书 20 页</strong><small>07:42 · 留给自己的安静时间</small></span><span class="plan-status done">${icon('check-circle')}已盖章</span></button><button class="plan-row" data-action="memo-view" data-id="meal"><span class="plan-icon">${icon('fork-knife')}</span><span class="plan-text"><strong>认真吃一餐</strong><small>12:15 · 今天也有好好吃饭</small></span><span class="plan-status done">${icon('check-circle')}已盖章</span></button><button class="together-line" data-nav="team" style="width:100%"><span class="avatar-stack">${avatar('安','b')}${avatar('可','c')}${avatar('川','d')}</span><p><strong>有人和你一起。</strong><br>${state.stamped?'3':'2'} 位队友已完成今日计划 ${icon('arrow-up-right')}</p></button>`;}
function checkin(){return `${topbar('记录这一刻')}<div class="flow-steps" aria-label="第 1 步，共 3 步"><span class="active"></span><span></span><span></span></div><h1 class="page-title">做过的事，<br>值得<span class="accent">被看见。</span></h1><p class="subcopy">选好照片，剩下的交给 AI 整理。<br>你可以在提交前修改每一张照片的分类。</p><div class="chips" aria-label="计划分类">${['ALL','学习','运动','饮食'].map(c=>`<button class="chip ${state.category===c?'selected':''}" aria-pressed="${state.category===c}" data-action="category" data-value="${c}">${c==='ALL'?icon('squares-four'):''}${c==='ALL'?'ALL · 自动归类':c}</button>`).join('')}</div><div class="section-head"><h2>选择示例照片</h2><span class="hint">${state.selected.length} / 9 张</span></div><div class="photo-picker">${allPhotos().map(p=>`<button class="photo-option ${state.selected.includes(p.id)?'selected':''}" data-action="select-photo" data-id="${p.id}" aria-pressed="${state.selected.includes(p.id)}" aria-label="选择${p.name}"><img src="${p.src}" alt="${p.name}" loading="lazy"><span class="select-marker">${state.selected.includes(p.id)?icon('check'):''}</span><span class="caption">${p.name}</span></button>`).join('')}</div><div class="source-line"><button data-action="photo-source" data-value="camera">${icon('camera')}拍一张</button><button data-action="photo-source" data-value="album">${icon('image')}从相册选择</button><button data-nav="timer">${icon('timer')}运动计时</button></div>${primary(state.selected.length?`整理 ${state.selected.length} 张照片`:'先选一张照片','recognize','arrow-right',!state.selected.length)}<p class="hint">此处为本地演示。示例图不校验真实拍摄时间。</p><div class="capture-tip">${icon('shield-check')}<span>正式版逐张验证当天日期，照片仅对所选范围可见。AI 暂不可用时，仍可先盖章。</span></div><button class="text-button" data-action="scenario-sheet" style="margin-top:12px">切换演示场景 ${icon('caret-down')}</button>`;}
function recognizing(){return `${topbar('整理照片','checkin')}<div class="flow-steps"><span class="active"></span><span class="active"></span><span></span></div><div class="loading-view"><img src="${selectedPhotos()[0]?.src||'assets/run.jpg'}" alt="正在整理的照片"><div class="loading-bars" aria-hidden="true"><span></span><span></span><span></span></div><h2>把这一刻，整理成记录。</h2><p class="subcopy">正在逐张归类和生成纪要<br>本地模拟识别，不发送照片</p>${secondary('跳过识别，先盖章','skip-ai')}</div>`;}
function categorySelect(p){return `<label class="sr-only" for="label-${p.id}">${p.name}的分类</label><select id="label-${p.id}" data-label-id="${p.id}">${['ALL','运动','学习','饮食'].map(c=>`<option ${state.labels[p.id]===c?'selected':''}>${c}</option>`).join('')}</select>`;}
function aggregateCategory(){const counts={};state.selected.forEach(id=>{const c=state.labels[id]||'ALL';counts[c]=(counts[c]||0)+1;});const rows=Object.entries(counts).sort((a,b)=>b[1]-a[1]);return !rows.length||(rows[1]&&rows[0][1]===rows[1][1])?'ALL':rows[0][0];}
function memo(){const pending=state.scenario==='timeout';return `${topbar('确认纪要','checkin')}<div class="flow-steps"><span class="active"></span><span class="active"></span><span></span></div><h1 class="page-title">这是你的<span class="accent">今天。</span></h1><p class="subcopy">分类与文字都可以改。记录以你的版本为准。</p>${pending?'<div class="inline-alert">识别暂不可用。可以先以 ALL 盖章，纪要显示「生成中」，当天内继续补识别。</div>':''}${state.oldRemoved?'<div class="inline-alert">已剔除 1 张非当天照片，其余照片可以继续打卡。正式版按实际拍摄日期检查。</div>':''}${selectedPhotos().map(p=>`<div class="memo-photo"><img src="${p.src}" alt="${p.name}"><div><strong>${p.name}</strong><p>${pending?'ALL · 等待补识别':`AI 识别 · 置信度 ${p.confidence}`} · 示例</p>${categorySelect(p)}</div></div>`).join('')}<div class="field"><label for="memo-text">今日纪要 <span style="font-weight:400;color:var(--muted)">${state.memoEdited?'· 已手动编辑':'· 可编辑'}</span></label><textarea id="memo-text" placeholder="补充你想记住的细节">${escapeText(state.notes)}</textarea></div>${pending?'':memoFacts()}<p class="hint">本次归类：${aggregateCategory()}。多图按多数结果归类，平票保留 ALL；逐图标签仍会保留。</p>${primary('确认，给今天盖章','stamp','check')}<p class="hint" style="text-align:center">盖章后 24 小时内仍可修改标签</p>`;}
function memoFacts(){const selected=selectedPhotos();let html='';if(selected.some(p=>state.labels[p.id]==='运动'))html+=`<div><small>运动时长</small><strong>${state.timerElapsed>0?timerText():'未记录'}</strong><span>${state.timerElapsed>0?'来源：应用计时 · 演示':'照片只证明到场'}</span></div><div><small>运动消耗</small><strong>未记录</strong><span>暂无截图或其他来源</span></div>`;if(selected.some(p=>state.labels[p.id]==='饮食'))html+='<div><small>热量区间 · 估算</small><strong>约 350–550 千卡</strong><span>来源：AI 识别示例</span></div><div><small>份量</small><strong>1 份</strong><span>可在纪要中补充</span></div>';if(selected.some(p=>state.labels[p.id]==='学习'))html+='<div><small>章节 / 页码</small><strong>未记录</strong><span>未从照片提取</span></div><div><small>关键词</small><strong>阅读</strong><span>来源：AI 识别示例</span></div>';return `<div class="facts">${html}</div>`;}
function success(){return `${topbar('这一刻，已记录')}<div class="success-view"><div class="success-seal">${icon('check')}</div><h1>你又向前了一点。</h1><p>已盖章 · 11 月 19 日<br>这份坚持，队友也看见了。</p><img class="success-photo" src="${selectedPhotos()[0]?.src||'assets/run.jpg'}" alt="本次打卡照片"><div class="success-summary">${state.scenario==='timeout'?'纪要生成中。打卡已完成，AI 将在当天内继续补识别。':escapeText(state.notes)}</div>${primary('去小队看看','go-team','users')}<button class="text-button" style="margin-top:13px" data-nav="today">回到今日 ${icon('arrow-right')}</button></div>`;}
function feedCard({self=false}={}){return `<article class="feed-item"><div class="feed-person">${avatar(self?'一':'安',self?'me':'b')}<div><strong>${self?'林一 · 我':'小安'}</strong><small>${self?'刚刚完成':'07:18 完成'} · ${self?'已盖章':'运动'}</small></div><span class="feed-time">${self?'刚刚':'今天'}</span></div><img class="feed-image" src="${self?selectedPhotos()[0]?.src||'assets/run.jpg':'assets/run.jpg'}" alt="${self?'我本次打卡的照片':'小安的户外运动照片'}" loading="lazy"><h3>${self?'把今天的这一刻，留下了。':'早一点出门，多一点风景。'}</h3><p>${self?(state.scenario==='timeout'?'纪要生成中，打卡已完成。':escapeText(state.notes)):'今天完成了户外运动。照片记录了出发，时长与消耗尚未记录。'}</p><div class="feed-tags"><span>仅小队可见</span><span>·</span><span>${self?'已盖章':'运动纪要'}</span></div><div class="feed-actions"><button data-action="like" aria-pressed="${state.liked}" class="${state.liked?'liked':''}">${icon('heart')}${state.liked?'3':'2'}</button><button data-action="comment" data-self="${self}">${icon('chat-circle')}回应</button>${self?'<button data-action="edit-stamped">'+icon('pencil')+'编辑纪要</button>':''}</div></article>`;}
function team(){return `${topbar()}<div class="section-head" style="margin-top:14px"><h1 class="page-title" style="margin:0">慢慢来<span class="accent">小队。</span></h1><button class="icon-btn" data-nav="invite" aria-label="邀请队友">${icon('plus')}</button></div><p class="subcopy" style="margin-top:12px">不用步调一致。一起向前就好。</p><div class="team-status"><div class="team-member">${avatar('一','me')}<strong>我</strong><small class="${state.stamped?'complete':''}">${state.stamped?'已完成':'进行中'}</small></div><div class="team-member">${avatar('安','b')}<strong>小安</strong><small class="complete">已完成</small></div><div class="team-member">${avatar('可','c')}<strong>可可</strong><small class="complete">已完成</small></div><div class="team-member">${avatar('川','d')}<strong>阿川</strong><small>未开始</small></div></div><div class="team-note"><span>${icon('lock-simple')} 4 / 5 人 · 私密小队</span><span>共同连续 6 天</span></div><div class="section-head"><h2>一起发生的日常</h2><span class="hint">今天</span></div>${state.reportShared?'<article class="feed-item"><div class="feed-person">'+avatar('一','me')+'<strong>林一分享了个人周报</strong></div><h3>那些很小的事，算在一起。</h3><p>本周完成 12 / 14 次，完成率 86%。仅包含本人信息。</p><button class="text-button" data-nav="report">打开周报 '+icon('arrow-right')+'</button></article>':''}${state.stamped?feedCard({self:true}):''}${feedCard()}<div class="overdue">${icon('clock')}<div><strong>阿川的「读书 20 页」还未完成</strong><small>截止 08:00 · 08:30 同步</small></div><button data-action="poke" ${state.poked?'disabled':''}>${state.poked?'已戳一下':'戳一下'}</button></div><p class="hint">小队时区 Asia/Shanghai · 所有截止时间按此计算</p>`;}
function report(){const mine=state.reportMode==='mine';return `${topbar()}<div class="section-head" style="margin-top:15px"><h1 class="page-title" style="margin:0">这一周<span class="accent">。</span></h1><button class="icon-btn" data-nav="history" aria-label="查看历史">${icon('calendar-blank')}</button></div><div class="segmented" role="group" aria-label="周报范围"><button data-action="report-mode" data-value="mine" class="${mine?'active':''}" aria-pressed="${mine}">我的周报</button><button data-action="report-mode" data-value="team" class="${!mine?'active':''}" aria-pressed="${!mine}">小队周报</button></div><section class="report-hero"><div class="report-period"><span>11.09 至 11.15</span><span>每周日 20:00 汇总</span></div><h1>${mine?'那些很小的事，<br>算在一起。':'四个人，<br>把一周过得更认真。'}</h1><div class="report-score"><strong>${mine?'86':'82'}<span>%</span></strong><p>${mine?'完成 12 / 14 次<br>比上周多完成 2 次':'全队完成 46 / 56 次<br>4 人 · 各自坚持'}</p></div><p class="subcopy">${mine?'你是这周打卡最积极的人。<br>12 次记录，每一次都有迹可循。':'这周共有 46 次记录。<br>跑过的路、读过的页，都有人看见。'}</p></section>${mine?`<div class="section-head"><h2>你的每一天</h2><span class="hint">每日 2 次计划</span></div><div class="rhythm" role="img" aria-label="周一至周日完成次数为 2、2、1、2、1、2、2，共 12 次"><div class="rhythm-day"><i></i><i></i><small>一</small></div><div class="rhythm-day"><i></i><i></i><small>二</small></div><div class="rhythm-day"><i></i><i class="rest"></i><small>三</small></div><div class="rhythm-day"><i></i><i></i><small>四</small></div><div class="rhythm-day"><i></i><i class="rest"></i><small>五</small></div><div class="rhythm-day"><i></i><i></i><small>六</small></div><div class="rhythm-day"><i></i><i></i><small>日</small></div></div><div class="legend"><span><i></i>已完成</span><span><i class="rest"></i>未完成</span></div><div class="report-detail"><span>运动</span><span>3 / 3 次 · 补卡 0 次</span></div><div class="report-detail"><span>学习</span><span>5 / 7 次 · 补卡 0 次</span></div><div class="report-detail"><span>饮食</span><span>4 / 4 次 · 补卡 0 次</span></div><div class="section-head"><h2>想记住的三个时刻</h2></div><div class="report-photos">${photoData.map((p,i)=>`<div><img src="${p.src}" alt="${p.name}" loading="lazy"><p>${['出门跑步的<br>那个早晨','留给阅读的<br>安静片刻','认真准备的<br>一餐蔬食'][i]}</p></div>`).join('')}</div><div class="suggestion"><h3>下周，把阅读放早一点。</h3><p>这周两次未完成的阅读都安排在晚间。试试将提醒提前到 20:00，给自己留一点余量。</p><button class="text-button" data-action="adopt">调整下周提醒 ${icon('arrow-right')}</button></div>${primary('发送到小队动态','share-report','share-network')}<div style="height:10px"></div>${secondary('保存个人周报长图','export-report','export')}<p class="hint" style="text-align:center">分享图仅包含本人数据，不带队友明细</p>`:`<div class="section-head"><h2>各自的坚持</h2><span class="hint">按成员展示，不作排名</span></div>${[['林一','12 / 14'],['小安','12 / 14'],['可可','12 / 14'],['阿川','10 / 14']].map(([n,v])=>`<div class="report-detail"><span>${n}</span><span>${v} 次完成</span></div>`).join('')}<div class="capture-tip">${icon('lock-simple')}<span>小队周报仅队内可见。对外分享请切换到个人周报。</span></div>`}`;}
const planData=[{id:'run',icon:'person-simple-run',title:'每周跑三次',goal:'每次给自己 30 分钟',freq:'周二、周四、周六',time:'21:00',done:2,total:3},{id:'book',icon:'book-open',title:'读书 20 页',goal:'每天留一点时间给阅读',freq:'每天',time:'22:00',done:4,total:7},{id:'meal',icon:'fork-knife',title:'认真吃一餐',goal:'记录一餐有蔬菜的食物',freq:'周一、周三、周五、周日',time:'20:00',done:2,total:4}];
function plans(){return `${topbar()}<div class="section-head" style="margin-top:14px"><h1 class="page-title" style="margin:0">给自己<span class="accent">的约定。</span></h1></div><p class="subcopy" style="margin-top:14px">不必一下子做很多。<br>先从这三件小事开始。</p><div class="section-head"><h2>进行中的计划</h2><span class="hint">3 / 3</span></div>${planData.map(p=>`<section class="plan-detail"><div class="plan-detail-head"><span class="plan-icon">${icon(p.icon)}</span><div><h2>${p.title}</h2><small>${p.goal}</small></div><button class="icon-btn" data-action="edit-plan" data-id="${p.id}" aria-label="编辑${p.title}">${icon('dots-three')}</button></div><div class="plan-schedule"><span>${p.freq}</span><span>${p.done} / ${p.total} 次</span></div><div class="progress-rail" aria-label="本周完成 ${p.done} 次，共 ${p.total} 次">${Array.from({length:p.total},(_,i)=>`<i class="${i<p.done?'complete':''}"></i>`).join('')}</div><div class="plan-meta"><span>${p.time} 前打卡</span><span>仅小队可见</span></div></section>`).join('')}<div style="height:24px"></div><button class="secondary" disabled>${icon('plus')}最多同时进行 3 个计划</button><p class="hint">结束一个已有计划后，就能开始新计划。</p><button class="text-button" data-nav="history">看看过去的记录 ${icon('arrow-right')}</button>`;}
function invite(){return `${topbar('邀请与加入','team')}<h1 class="page-title">把下一步，<br>留给<span class="accent">我们。</span></h1><p class="subcopy">邀请熟悉的人，组成 2–5 人小队。<br>每个人有自己的计划，相互看见就好。</p><section class="invite-card"><h2>慢慢来小队</h2><p>4 人同行 · 还有 1 个位置</p><div class="qr" id="invite-qr" aria-label="仅用于此原型的演示二维码"></div><div class="invite-code">BT26 8K7M</div><p>8 位邀请码 · 演示码<br>仅供原型体验，不能加入真实小队</p><button class="text-button" data-action="copy-code">${icon('copy')}复制邀请码</button></section><div class="button-row">${secondary('扫码加入','go-scan','scan')}${secondary('输入邀请码','go-join','qr-code')}</div><p class="hint">正式版支持相机扫描。此原型通过模拟识别体验确认流程。</p>`;}
function scanner(){return `${topbar('扫码加入','invite')}<h1 class="page-title">扫一下，<br>一起<span class="accent">出发。</span></h1><p class="subcopy">将队友的邀请二维码放入取景框。</p><div class="scan-frame">${icon('scan')}</div><p class="hint" style="text-align:center">原型不申请相机权限，不读取二维码内容</p>${primary('模拟识别邀请二维码','scan-result','check')}<button class="text-button" style="display:flex;width:100%;margin-top:12px" data-nav="join">改为手动输入</button>`;}
function join(){return `${topbar('加入小队','invite')}<h1 class="page-title">找到你<span class="accent">的同伴。</span></h1><p class="subcopy">向队友要一个邀请码，或扫描邀请二维码。</p><div class="field"><label for="join-code">8 位邀请码</label><input id="join-code" type="text" maxlength="9" autocapitalize="characters" autocomplete="off" placeholder="例如 BT26 8K7M" value="${escapeText(state.joinCode)}" style="font-size:24px;letter-spacing:3px"><p class="hint">演示有效码：BT26 8K7M</p><p class="error-text" id="join-error" role="alert"></p></div>${primary('确认邀请码','validate-code','arrow-right')}<div class="capture-tip">${icon('lock-simple')}<span>确认队名和固定时区后再加入。演示不会修改你的真实小队。</span></div>`;}
function settings(){return `${topbar('我的与设置')}<div class="profile-head">${avatar('一','me')}<div><h1>林一</h1><p>正在和 3 位同伴一起向前</p></div></div><button class="settings-row" data-action="profile">${icon('pencil')}<span class="setting-info">个人资料<small>头像与昵称</small></span>${icon('caret-right')}</button><button class="settings-row" data-nav="ai">${icon('lightning')}<span class="setting-info">我的 AI<small>${state.aiSaved?'已保存演示配置':'自定义识别接口与模型'}</small></span>${icon('caret-right')}</button><button class="settings-row" data-action="notification-settings">${icon('bell')}<span class="setting-info">通知偏好<small>戳一下、周报与小队互动</small></span>${icon('caret-right')}</button><button class="settings-row" data-action="privacy">${icon('shield-check')}<span class="setting-info">隐私与可见范围<small>照片默认仅小队可见</small></span>${icon('caret-right')}</button><button class="settings-row" data-action="theme" role="switch" aria-checked="${state.theme==='dark'}">${icon('moon')}<span class="setting-info">深色模式</span><span class="switch ${state.theme==='dark'?'on':''}"></span></button><button class="settings-row" data-action="makeup">${icon('calendar-blank')}<span class="setting-info">补卡与暂停周<small>本月剩余 2 张补卡</small></span>${icon('caret-right')}</button><button class="settings-row" data-action="health">${icon('heart')}<span class="setting-info">健康数据<small>尚未开放，当前版本不会读取</small></span>${icon('caret-right')}</button><button class="settings-row" data-action="delete-account">${icon('trash')}<span class="setting-info">删除账户</span>${icon('caret-right')}</button><div class="privacy-foot">${icon('lock-simple')}你的日常，只和你选择的人分享</div><button class="text-button" data-action="overview" style="display:flex;width:100%;margin-top:18px">查看原型体验路线</button>`;}
function ai(){return `${topbar('我的 AI','settings')}<h1 class="page-title">让 AI，<br>按你的<span class="accent">方式工作。</span></h1><p class="subcopy">选择你信任的识别服务，帮你整理照片。<br>所有配置仅在此原型内演示。</p><div class="field"><label for="ai-url">API 接口地址</label><input id="ai-url" type="url" value="https://api.siliconflow.cn/v1" autocomplete="off"></div><div class="field"><label for="ai-model">模型名称</label><input id="ai-model" value="deepseek-ai/DeepSeek-V4.1-Flash" autocomplete="off"></div><div class="field"><label for="ai-key">API 密钥</label><input id="ai-key" type="password" placeholder="原型请勿输入真实密钥" autocomplete="off"><p class="hint">这里不会保存或发送密钥。正式版通过后端安全保存，客户端不直接调用 AI。</p></div><p class="error-text" id="ai-error" role="alert"></p>${secondary('测试演示连接','test-ai','lightning')}<div style="height:10px"></div>${primary('保存演示配置','save-ai','check')}<div class="capture-tip">${icon('cloud-slash')}<span>识别暂不可用时，可以以 ALL 先盖章，再补生成纪要。</span></div>`;}
function notifications(){return `${topbar('通知')}<h1 class="page-title">来自<span class="accent">同伴。</span></h1><div class="notification-item">${icon('heart')}<div><h3>小安看见了你的阅读记录</h3><p>给你的「读书 20 页」点了赞。</p><small>今天 08:12</small></div></div><div class="notification-item">${icon('chart-bar')}<div><h3>上周的坚持，整理好了</h3><p>12 次记录，一份只属于你的周报。</p><button class="text-button" data-nav="report">打开周报 ${icon('arrow-right')}</button><small>周日 20:00</small></div></div><div class="section-head"><h2>没有更多未读消息了</h2></div><p class="hint">你可以在设置里单独关闭各类通知。</p>`;}
function timer(){return `${topbar('运动计时','checkin')}<h1 class="page-title">专注于<span class="accent">这一步。</span></h1><p class="subcopy">计时可作为运动时长来源。<br>原型计时只在当前页面保持运行。</p><div class="timer" id="timer-value">${timerText()}</div><p class="timer-state" id="timer-state">${state.timerStart?'计时中，按自己的节奏来':'准备好，就开始'}</p>${primary(state.timerStart?'暂停计时':'开始计时','toggle-timer',state.timerStart?'pause':'play')}<div style="height:10px"></div>${secondary('结束并选择照片','finish-timer','camera')}`;}
function timerText(){const sec=Math.floor((state.timerElapsed+(state.timerStart?Date.now()-state.timerStart:0))/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function history(){return `${topbar('打卡历史','plans')}<h1 class="page-title">走过的，<br>都<span class="accent">算数。</span></h1><p class="subcopy">11 月的日常 · 仅本人记录</p><div class="section-head"><h2>11 月 19 日</h2><span class="hint">${state.stamped?'3':'2'} 条记录</span></div>${(state.stamped?photoData:photoData.slice(1)).map(p=>`<button class="plan-row" data-action="memo-view" data-id="${p.id}"><img src="${p.src}" alt="${p.name}" style="width:60px;height:70px;object-fit:cover;border-radius:12px"><span class="plan-text"><strong>${p.name}</strong><small>${p.category} · 已盖章</small></span>${icon('caret-right')}</button>`).join('')}<div class="empty-message">${icon('calendar-blank')}<h3>更早的记录，等你来写。</h3><p>此原型仅展示今天的示例内容。</p></div>`;}
const renderers={today,checkin,recognizing,memo,success,team,report,plans,invite,scanner,join,settings,ai,notifications,timer,history};
const notes={
 today:['把行动，放回首页。','第一眼看见今天想做的事。照片提供情境，完成状态只在需要的地方出现。',[['时间有了节奏','日期、截止时间和完成记录保持同一条阅读路径。'],['熟悉的人就在下面','队友头像不是排名入口，而是一起坚持的提醒。']]],
 checkin:['先记录，再整理。','用一个轻量任务流接住所有类别。保持 ALL 默认，再逐张确认识别结果。',[['照片先于表单','以选图开始，避免先填写大量字段。'],['不中断努力','识别暂不可用时，明确提供先盖章的路径。']]],
 team:['一张小队的生活切片。','成员状态在上，具体日常在下。保留私密、轻监督的关系，不制造排行榜。',[['每个人有自己的速度','状态只陈述进度，不给人贴负面标签。'],['动作按内容区分','已盖章记录可回应，逾期动态只有戳一下。']]],
 report:['用时刻，解释数字。','完成率给出事实，照片和纪要赋予它意义。让周报成为愿意留存的一周，而非成绩单。',[['一格对应一次约定','节奏图有明确分母，所有统计均可读懂。'],['分享有边界','导出的长图只含本人数据与称号。']]],
 plans:['少一些，才能坚持。','三个计划完整呈现，目标、频率、截止时间都有稳定的位置。',[['计划无需打开才能理解','每周频率与已完成次数直接可见。'],['编辑保持轻量','聚焦单个计划，用底部弹层完成修改。']]],
 settings:['把选择权交还给你。','个性化 AI、通知与隐私放在同一套清晰的设置语言里。',[['配置不等于授权照片','原型不联网识别，不存储密钥。'],['深浅色是同一套逻辑','对比度、层级与操作位置保持一致。']]],
 invite:['邀请，短一点。','二维码负责见面时的快速加入，8 位短码方便手动输入。',[['确认后再加入','识别后展示队名、人数和固定时区。'],['演示边界清晰','二维码只通向本地原型，不创建真实邀请。']]]
};
function updateNotes(route){const key=notes[route]?route:['memo','recognizing','success','timer'].includes(route)?'checkin':['scanner','join'].includes(route)?'invite':'settings';const [title,body,items]=notes[key];$('#note-content').innerHTML=`<h2>${title}</h2><p>${body}</p><div class="note-rule"></div>${items.map(([h,p])=>`<div class="note-item"><strong>${h}</strong><span>${p}</span></div>`).join('')}`;}
function render(){const route=location.hash.slice(1).split('?')[0]||'today';activeRoute=renderers[route]?route:'today';if(['memo','recognizing','success'].includes(activeRoute)&&!state.selected.length){location.replace('#checkin');activeRoute='checkin';}clearTimeout(recognitionTimer);$('#screen').innerHTML=renderers[activeRoute]();$('#stage-page').textContent=pages[activeRoute];const navActive=['memo','recognizing','success','timer'].includes(activeRoute)?'checkin':['invite','scanner','join'].includes(activeRoute)?'team':activeRoute;$('#tabbar').innerHTML=navItems.map(n=>`<button class="tab ${n.id===navActive?'active':''} ${n.id==='checkin'?'capture':''}" data-nav="${n.id}" ${n.id===navActive?'aria-current="page"':''} aria-label="${n.label}">${icon(n.icon)}<span>${n.label}</span></button>`).join('');$('#tabbar').hidden=['recognizing','memo','success','scanner'].includes(activeRoute);$('#review-nav').innerHTML=[...navItems.filter(n=>n.id!=='checkin'),{id:'invite',label:'邀请与加入',icon:'qr-code'},{id:'settings',label:'我的与设置',icon:'gear'}].map(n=>`<a class="review-link ${n.id===navActive?'active':''}" href="#${n.id}">${n.label}${icon('arrow-up-right')}</a>`).join('');$('#app-scroll').scrollTop=0;updateNotes(activeRoute);$('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#reset').innerHTML=icon('arrow-counter-clockwise');if(activeRoute==='invite')drawQR();if(activeRoute==='recognizing')recognitionTimer=setTimeout(finishRecognition,1350);if(activeRoute==='timer')startTimerDisplay();}
function navigate(route){if(location.hash===`#${route}`)render();else location.hash=route;}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function sheet(title,body){$('#sheet-body').innerHTML=`<div class="sheet-top"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close-sheet" aria-label="关闭">${icon('x')}</button></div>${body}`;if(!$('#sheet').open)$('#sheet').showModal();}
function closeSheet(){$('#sheet').close();}
function drawQR(){const qr=qrcode(0,'M');const u=new URL(location.href);u.hash='join';qr.addData(u.href);qr.make();$('#invite-qr').innerHTML=qr.createImgTag(6,2,'仅供原型体验的邀请二维码');}
function finishRecognition(){if(activeRoute!=='recognizing')return;state.oldRemoved=false;if(state.scenario==='old'){const remove=state.selected[state.selected.length-1];state.selected=state.selected.filter(id=>id!==remove);state.oldRemoved=true;if(!state.selected.length){navigate('checkin');toast('这张示例被设为非当天照片。换一张，或切回正常识别场景。');return;}}selectedPhotos().forEach(p=>state.labels[p.id]=state.scenario==='timeout'?'ALL':state.category==='ALL'?p.category:state.category);state.notes=state.scenario==='timeout'?'':selectedPhotos().map(p=>p.memo).join('\n');state.memoEdited=false;navigate('memo');}
function startTimerDisplay(){clearInterval(timerTick);timerTick=setInterval(()=>{if(activeRoute==='timer'&&$('#timer-value'))$('#timer-value').textContent=timerText();},250);}
function setTheme(){state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;$('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');if(activeRoute==='settings')render();}
function overview(){sheet('从今天，走完这一圈',`<p class="sheet-copy">这是独立的 UI 审核原型。数据、识别和邀请均为演示，现有 App 不受影响。</p>${[['checkin','camera','选照片 → 改分类 → 编辑纪要 → 盖章'],['team','users','看小队日常 → 点赞 / 回应 / 戳一下'],['invite','qr-code','短邀请码 → 模拟扫码 → 确认小队'],['report','chart-bar','个人 / 小队周报 → 保存个人长图'],['settings','gear','自定义 AI → 通知 → 深色模式']].map(([id,ic,t])=>`<button class="sheet-route" data-nav="${id}">${icon(ic)}${t}</button>`).join('')}<p class="hint">设计方向：同频。钴蓝、雾白、共享时间轴与真实照片。</p>`);}
async function copyCode(){try{await navigator.clipboard.writeText('BT268K7M');toast('已复制演示邀请码：BT268K7M');}catch{sheet('复制邀请码','<p class="sheet-copy">浏览器不允许自动复制，请长按选择下面的演示邀请码。</p><input aria-label="演示邀请码" value="BT268K7M" readonly style="width:100%;padding:15px;font-size:24px">');}}
function startUpload(source){sheet(source==='camera'?'拍一张':'从相册选择',`<p class="sheet-copy">这是浏览器原型。你可以选择本机照片预览，照片仅留在当前浏览器内，不上传、不做真实识别。</p><div class="field"><label for="local-photos">选择照片（最多 9 张）</label><input type="file" id="local-photos" accept="image/*" multiple ${source==='camera'?'capture="environment"':''}></div><p class="hint">也可以关闭此窗口，用三个示例照片完整体验。</p>`);$('#local-photos').addEventListener('change',event=>{const files=Array.from(event.target.files||[]);const available=9-state.selected.length;const valid=files.filter(f=>f.type.startsWith('image/')).slice(0,available);valid.forEach((f,i)=>{const id=`local-${Date.now()}-${i}`;customPhotos.push({id,src:URL.createObjectURL(f),name:'本机照片',category:'ALL',confidence:'未识别',memo:'本机照片预览。原型未执行真实 AI 识别，请手动补充纪要。'});state.selected.push(id);state.labels[id]='ALL';});closeSheet();render();toast(valid.length?`已加入 ${valid.length} 张本机照片，仅在浏览器内预览。`:'未添加照片。请选择图片，或先移除一些照片。');});}
function planEditor(id){const p=planData.find(p=>p.id===id);sheet('编辑这份约定',`<form id="plan-form"><div class="field"><label for="plan-title">计划名称</label><input id="plan-title" value="${escapeText(p.title)}" maxlength="24" required></div><div class="field"><label for="plan-time">每日截止时间</label><input id="plan-time" type="time" value="${p.time}" required></div><p class="hint">固定时区 Asia/Shanghai。原型修改只保留到刷新页面。</p><button class="primary" type="submit">保存修改 ${icon('check')}</button></form>`);$('#plan-form').addEventListener('submit',event=>{event.preventDefault();p.title=$('#plan-title').value.trim()||p.title;p.time=$('#plan-time').value;closeSheet();render();toast('计划已在原型中更新。');});}
function comment(self){sheet('回应这一刻',`<form id="comment-form"><p class="sheet-copy">${self?'给自己的记录补充一句。':'给小安留一句话。'}</p><div class="field"><label for="comment-text">回应内容</label><textarea id="comment-text" placeholder="我想说…" required maxlength="300"></textarea></div>${self?'':`<label class="check-row"><input type="checkbox" id="question-check">对本次打卡提出质疑</label><p class="hint">质疑需写明理由。4 人小队需 3 位队友质疑才触发重打，每人每天最多 2 次。</p>`}<p class="error-text" id="comment-error"></p><button class="primary" type="submit">发送演示回应 ${icon('arrow-right')}</button></form>`);$('#comment-form').addEventListener('submit',e=>{e.preventDefault();const value=$('#comment-text').value.trim();if(!value){$('#comment-error').textContent='请写一句回应或质疑理由。';return;}const q=$('#question-check')?.checked;closeSheet();toast(q?'已记录演示质疑：1 / 3 人，盖章状态保持不变。':'演示回应已发送，没有发送给真实队友。');});}
function exportReport(){const c=document.createElement('canvas');c.width=1000;c.height=1770;const ctx=c.getContext('2d');ctx.fillStyle='#f7f8fa';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#191b20';ctx.font='700 34px Manrope, sans-serif';ctx.fillText('better together.',70,90);ctx.font='26px sans-serif';ctx.fillStyle='#626872';ctx.fillText('林一的个人周报 · 示例数据',70,155);ctx.fillText('2026.11.09 至 11.15',70,200);ctx.fillStyle='#191b20';ctx.font='600 65px sans-serif';ctx.fillText('那些很小的事，',70,340);ctx.fillText('算在一起。',70,425);ctx.fillStyle='#2854dc';ctx.font='600 200px Manrope, sans-serif';ctx.fillText('86%',62,680);ctx.fillStyle='#626872';ctx.font='32px sans-serif';ctx.fillText('完成 12 / 14 次 · 比上周多完成 2 次',70,755);ctx.fillStyle='#191b20';ctx.font='600 35px sans-serif';ctx.fillText('你是这周打卡最积极的人',70,855);const bars=[2,2,1,2,1,2,2];bars.forEach((v,i)=>{for(let j=0;j<2;j++){ctx.fillStyle=j<v?'#2854dc':'#e1e5eb';ctx.fillRect(70+i*125,950+j*55,104,40);}ctx.fillStyle='#626872';ctx.font='24px sans-serif';ctx.fillText(['周一','周二','周三','周四','周五','周六','周日'][i],90+i*125,1095);});ctx.fillStyle='#191b20';ctx.font='30px sans-serif';['运动 3 / 3 次 · 学习 5 / 7 次 · 饮食 4 / 4 次','跑过的路，读过的页，认真吃过的一餐。','每一次记录，都有自己的意义。'].forEach((t,i)=>ctx.fillText(t,70,1210+i*70));ctx.fillStyle='#2854dc';ctx.font='600 48px sans-serif';ctx.fillText('各自的节奏。共同的日常。',70,1545);ctx.fillStyle='#626872';ctx.font='24px sans-serif';ctx.fillText('UI 审核原型 · 示例数据 · 仅包含本人内容',70,1650);const a=document.createElement('a');a.download='Better-Together-个人周报-示例.png';a.href=c.toDataURL('image/png');a.click();toast('个人周报示例长图已生成，不含队友明细。');}
const actions={
 'overview':overview,'close-sheet':closeSheet,'theme':setTheme,'copy-code':copyCode,
 'category':el=>{state.category=el.dataset.value;render();},
 'select-photo':el=>{const id=el.dataset.id;if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<9)state.selected.push(id);else toast('每次最多选择 9 张照片。');render();},
 'recognize':()=>{if(state.selected.length)navigate('recognizing');},
 'skip-ai':()=>{state.scenario='timeout';finishRecognition();},
 'stamp':()=>{state.notes=$('#memo-text').value;state.stamped=true;navigate('success');},
 'go-team':()=>navigate('team'),'go-scan':()=>navigate('scanner'),'go-join':()=>navigate('join'),
 'like':()=>{state.liked=!state.liked;const scroll=$('#app-scroll').scrollTop;render();$('#app-scroll').scrollTop=scroll;},
 'comment':el=>comment(el.dataset.self==='true'),
 'poke':()=>{state.poked=true;const scroll=$('#app-scroll').scrollTop;render();$('#app-scroll').scrollTop=scroll;toast('已戳一下，演示中不会给真实队友发送通知。');},
 'report-mode':el=>{state.reportMode=el.dataset.value;render();},
 'share-report':()=>{state.reportShared=true;toast('个人周报已加入演示小队动态。');},
 'export-report':exportReport,
 'adopt':()=>sheet('将阅读提醒提前',`<p class="sheet-copy">下周将「读书 20 页」的提醒设为 20:00，截止时间仍为 22:00。此操作仅在原型中演示。</p>${primary('采纳这个建议','confirm-adopt','check')}`),
 'confirm-adopt':()=>{closeSheet();toast('已采纳演示建议，下周 20:00 提醒阅读。');},
 'edit-plan':el=>planEditor(el.dataset.id),
 'photo-source':el=>startUpload(el.dataset.value),
 'scan-result':()=>{state.joinCode='BT26 8K7M';navigate('join');toast('已模拟识别，确认邀请码后查看小队。');},
 'validate-code':()=>{const value=$('#join-code').value.replace(/\s/g,'').toUpperCase();state.joinCode=$('#join-code').value;if(value!=='BT268K7M'){$('#join-error').textContent='演示邀请码不匹配，请输入 BT26 8K7M。';return;}sheet('是你要找的小队吗？',`<h3>慢慢来小队</h3><p class="sheet-copy">4 / 5 人 · 邀请人：小安<br>固定时区：Asia/Shanghai<br>所有打卡截止时间按此时区计算。</p><p class="hint">这是演示加入，不会修改真实账号的小队关系。</p>${primary('确认加入演示小队','confirm-join','check')}`);},
 'confirm-join':()=>{state.joined=true;closeSheet();navigate('team');toast('已完成加入流程演示。真实小队保持不变。');},
 'edit-stamped':()=>{navigate('memo');},
 'memo-view':el=>{const p=photoData.find(p=>p.id===el.dataset.id);sheet('这一天的纪要',`<img class="success-photo" src="${p.src}" alt="${p.name}" style="margin-top:0"><h3>${p.name} · 已盖章</h3><p class="sheet-copy">${p.memo}</p><p class="hint">示例记录 · 仅小队可见<br>${p.id==='run'?'运动时长与消耗：未记录，无来源不估算。':p.id==='meal'?'热量约 350–550 千卡，AI 估算示例。':'章节与页码：未记录。'}</p>${secondary('关闭','close-sheet')}`);},
 'profile':()=>{sheet('个人资料','<div class="field"><label for="nickname">昵称</label><input id="nickname" value="林一" maxlength="20"></div><p class="hint">此原型用固定示例人物展示界面。</p>'+primary('保存演示资料','save-profile','check'));},
 'save-profile':()=>{closeSheet();toast('已体验资料保存，原型继续使用示例人物「林一」。');},
 'notification-settings':()=>sheet('通知偏好',`<p class="sheet-copy">按你需要的节奏接收消息。</p>${['全部通知','戳一下','逾期同步','周报','点赞评论','质疑'].map((label,i)=>`<label class="check-row" style="justify-content:space-between;border-bottom:1px solid var(--line);padding:12px 0"><span>${label}</span><input type="checkbox" checked data-notify="${i}"></label>`).join('')}<div style="height:16px"></div>${primary('保存演示偏好','save-notifications','check')}`),
 'save-notifications':()=>{closeSheet();toast('通知偏好已在演示中保存。');},
 'privacy':()=>sheet('由你决定谁能看见',`<p class="sheet-copy">打卡照片默认仅小队可见；计划也可以设为仅自己可见。退出小队后，历史内容仅本人可见。</p><p class="sheet-copy">正式版原图使用私有存储和签名链接，保留至你主动删除。</p>${secondary('知道了','close-sheet')}`),
 'makeup':()=>sheet('补卡与暂停周','<h3>本月还剩 2 张补卡</h3><p class="sheet-copy">次日 12:00 前可补前一天，并写一句原因。补卡保持本周完成率，连续记录冻结，不增加也不清零。</p><p class="hint">暂停周不产生逾期动态。这里仅展示规则，不修改真实计划。</p>'+secondary('知道了','close-sheet')),
 'health':()=>sheet('健康数据尚未开放','<p class="sheet-copy">当前版本不会读取 HealthKit。运动时长可来自应用计时、运动截图或手动填写，都会标注来源。</p>'+secondary('知道了','close-sheet')),
 'delete-account':()=>sheet('删除账户','<p class="sheet-copy">正式版在这里展示删除范围并再次确认。当前是 UI 原型，没有真实账户，也不会执行删除。</p>'+secondary('返回设置','close-sheet')),
 'test-ai':()=>{const input=$('#ai-url');try{const u=new URL(input.value);if(u.protocol!=='https:')throw Error();$('#ai-error').textContent='';toast('演示连接成功。未发送网络请求，也未验证真实模型能力。');}catch{$('#ai-error').textContent='请输入以 https:// 开头的有效接口地址。';}},
 'save-ai':()=>{try{const u=new URL($('#ai-url').value);if(u.protocol!=='https:'||!$('#ai-model').value.trim())throw Error();$('#ai-key').value='';state.aiSaved=true;toast('演示配置已保存，密钥输入已清空。刷新后不保留。');}catch{$('#ai-error').textContent='请填写有效 HTTPS 接口地址和模型名称。';}},
 'toggle-timer':()=>{if(state.timerStart){state.timerElapsed+=Date.now()-state.timerStart;state.timerStart=null;}else state.timerStart=Date.now();render();},
 'finish-timer':()=>{if(state.timerStart){state.timerElapsed+=Date.now()-state.timerStart;state.timerStart=null;}navigate('checkin');toast(`演示计时 ${timerText()}。请选择当天照片作为凭证。`);},
 'scenario-sheet':()=>sheet('选择演示场景',`${[['normal','正常识别'],['timeout','AI 暂不可用'],['old','含一张非当天照片']].map(([v,t])=>`<button class="sheet-route" data-action="scenario-choice" data-value="${v}">${icon(state.scenario===v?'check-circle':'circle')}${t}</button>`).join('')}<p class="hint">场景只影响下一次示例识别。</p>`),
 'scenario-choice':el=>{state.scenario=el.dataset.value;$('#scenario').value=state.scenario;closeSheet();toast('已切换演示场景。选择照片后点击整理。');}
};
document.addEventListener('click',event=>{const nav=event.target.closest('[data-nav]');if(nav){closeSheet();navigate(nav.dataset.nav);return;}const el=event.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);});
document.addEventListener('change',event=>{if(event.target.matches('[data-label-id]')){state.labels[event.target.dataset.labelId]=event.target.value;state.notes=$('#memo-text').value;state.memoEdited=true;const scroll=$('#app-scroll').scrollTop;render();$('#app-scroll').scrollTop=scroll;toast('分类已更新；已编辑的纪要会保留。');}if(event.target.matches('[data-notify="0"]'))document.querySelectorAll('[data-notify]').forEach(input=>input.checked=event.target.checked);});
document.addEventListener('input',event=>{if(event.target.id==='memo-text'){state.notes=event.target.value;state.memoEdited=true;}});
$('#scenario').addEventListener('change',event=>state.scenario=event.target.value);
$('#theme-toggle').addEventListener('click',setTheme);
$('#reset').addEventListener('click',()=>{customPhotos.forEach(p=>URL.revokeObjectURL(p.src));customPhotos=[];state=initialState();document.documentElement.dataset.theme='light';$('#scenario').value='normal';navigate('today');toast('演示已重置，可以从头体验。');});
$('#sheet').addEventListener('click',event=>{if(event.target===$('#sheet'))closeSheet();});
window.addEventListener('hashchange',render);
window.addEventListener('beforeunload',()=>customPhotos.forEach(p=>URL.revokeObjectURL(p.src)));
render();
